import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

/** Create an independent decoder for the small line-framed protocol. */
export function createDecoder(){
  const utf8=new TextDecoder('utf-8',{fatal:true});
  let text='';
  let data=[];
  let event;
  let terminated=false;
  let finished=false;
  let poisoned=false;

  const fail=(error)=>{
    poisoned=true;
    throw error instanceof Error ? error : new Error(String(error));
  };
  const reset=()=>{ data=[]; event=undefined; };
  const line=(value,frames)=>{
    if(terminated){
      if(value!=='')throw new Error('content after termination');
      return;
    }
    if(value===''){
      if(data.length){
        const joined=data.join('\n');
        const name=event ? event : 'message';
        reset();
        if(joined==='[DONE]')terminated=true;
        else frames.push({event:name,data:joined});
      }else reset();
      return;
    }
    if(value.startsWith(':'))return;
    const colon=value.indexOf(':');
    const field=colon<0 ? value : value.slice(0,colon);
    let fieldValue=colon<0 ? '' : value.slice(colon+1);
    if(fieldValue.startsWith(' '))fieldValue=fieldValue.slice(1);
    if(field==='data')data.push(fieldValue);
    else if(field==='event')event=fieldValue;
  };
  const ensureActive=()=>{
    if(poisoned)throw new Error('decoder is poisoned');
    if(finished)fail(new Error('decoder is finished'));
  };

  return {
    push(chunk){
      try{
        ensureActive();
        if(!(chunk instanceof Uint8Array))throw new Error('chunk must be a Uint8Array');
        text+=utf8.decode(chunk,{stream:true});
        const frames=[];
        let newline;
        while((newline=text.indexOf('\n'))>=0){
          let complete=text.slice(0,newline);
          text=text.slice(newline+1);
          if(complete.endsWith('\r'))complete=complete.slice(0,-1);
          line(complete,frames);
        }
        return frames;
      }catch(error){ return fail(error); }
    },
    finish(){
      try{
        ensureActive();
        text+=utf8.decode();
        if(text!=='')throw new Error('unterminated line');
        if(data.length || event!==undefined)throw new Error('pending frame');
        if(!terminated)throw new Error('missing termination marker');
        finished=true;
        return [];
      }catch(error){ return fail(error); }
    },
  };
}

function decodeBase64(value){
  if(typeof value!=='string')throw new Error('chunks must contain strings');
  const bytes=Buffer.from(value,'base64');
  if(bytes.toString('base64')!==value)throw new Error('invalid canonical base64');
  return bytes;
}

function runCli(){
  try{
    if(process.argv.length!==3)throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
    const input=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
    if(input===null || Array.isArray(input) || typeof input!=='object' || !Array.isArray(input.chunks)){
      throw new Error('input must be an object with chunks array');
    }
    const decoder=createDecoder();
    const frames=[];
    for(const encoded of input.chunks)frames.push(...decoder.push(decodeBase64(encoded)));
    frames.push(...decoder.finish());
    process.stdout.write(JSON.stringify({frames})+'\n');
  }catch(error){
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode=2;
  }
}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))runCli();

