import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

function decode(parts){
  const d=createDecoder(),out=[];
  for(const part of parts)out.push(...d.push(part));
  assert.deepEqual(d.finish(),[]);
  return out;
}

test('all transport partitions, including bytes, give identical frames',()=>{
  const wire=Buffer.from('\ufeffevent: snow\r\ndata: 雪😀\ndata: second\n\ndata: [DONE]\n\n');
  const expected=[{event:'snow',data:'雪😀\nsecond'}];
  assert.deepEqual(decode([wire]),expected);
  for(let i=0;i<=wire.length;i++)assert.deepEqual(decode([wire.subarray(0,i),wire.subarray(i)]),expected);
  assert.deepEqual(decode([...wire].map(byte=>Uint8Array.of(byte))),expected);
});

test('parsing preserves protocol details and resets empty frames',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event: old\n: note\nx: ignored\n\ndata: a\rb\ndata\nevent:\n\n')),[
    {event:'message',data:'a\rb\n'}]);
  assert.deepEqual(d.push(Buffer.from('data: \ufeffx\n\ndata: [DONE]\n\n')), [{event:'message',data:'\ufeffx'}]);
  assert.deepEqual(d.finish(),[]);
});

test('strict UTF-8, unfinished input, DONE rules, and failures poison only one decoder',()=>{
  const bad=createDecoder();
  assert.deepEqual(bad.push(Uint8Array.of(0xc3)),[]);
  assert.throws(()=>bad.finish(),Error);
  assert.throws(()=>bad.push(new Uint8Array()),Error);
  const invalidUtf8=createDecoder();
  assert.throws(()=>invalidUtf8.push(Uint8Array.of(0xc3,0x28)),Error);
  const split=createDecoder();
  assert.deepEqual(split.push(Uint8Array.of(0xc3)),[]);
  assert.deepEqual(split.push(Uint8Array.of(0xa9)),[]);
  assert.deepEqual(split.push(Buffer.from('\ndata: [DONE]\n\n')),[]);
  assert.deepEqual(split.finish(),[]);
  const incomplete=createDecoder();
  incomplete.push(Buffer.from('data: x'));
  assert.throws(()=>incomplete.finish(),Error);
  assert.throws(()=>incomplete.push(new Uint8Array()),Error);
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: good\n\ndata: [DONE]\n\n')),[{event:'message',data:'good'}]);
  assert.throws(()=>d.push(Buffer.from(': forbidden\n')),Error);
  const okay=createDecoder();
  okay.push(Buffer.from('data: [DONE]\n\n\n'));
  assert.deepEqual(okay.finish(),[]);
  assert.throws(()=>createDecoder().push('not bytes'),Error);
});

