+  assert.deepEqual(split.push(Buffer.from('\ndata: [DONE]\n\n')),[]);
+  assert.deepEqual(split.finish(),[]);
+  const incomplete=createDecoder();
+  incomplete.push(Buffer.from('data: x'));
+  assert.throws(()=>incomplete.finish(),Error);
+  assert.throws(()=>incomplete.push(new Uint8Array()),Error);
+  const d=createDecoder();
+  assert.deepEqual(d.push(Buffer.from('data: good\n\ndata: [DONE]\n\n')),[{event:'message',data:'good'}]);
+  assert.throws(()=>d.push(Buffer.from(': forbidden\n')),Error);
+  const okay=createDecoder();
+  okay.push(Buffer.from('data: [DONE]\n\n\n'));
+  assert.deepEqual(okay.finish(),[]);
+  assert.throws(()=>createDecoder().push('not bytes'),Error);
+});
+
+test('CLI validates envelope, canonical base64, protocol, and output',()=>{
+  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'framer-'));
+  try{
+    const run=(input)=>{
+      const file=path.join(dir,'input.json');
+      fs.writeFileSync(file,JSON.stringify(input));
+      return spawnSync(process.execPath,['stream-framer.js',file],{encoding:'utf8'});
+    };
+    const good=run({chunks:[Buffer.from('data: hi\n\ndata: [DONE]\n\n').toString('base64')],extra:true});
+    assert.equal(good.status,0);assert.equal(good.stderr,'');
+    assert.equal(good.stdout,'{"frames":[{"event":"message","data":"hi"}]}\n');
+    const invalid=[null,[],{}, {chunks:'x'}, {chunks:['Zg']}, {chunks:['Zh==']}, {chunks:['Zm8= ']}, {chunks:['____']}, {chunks:[Buffer.from('data: x\n\n').toString('base64')]}];
+    for(const input of invalid){
+      const result=run(input);
+      assert.equal(result.status,2);assert.equal(result.stdout,'');assert.notEqual(result.stderr,'');
+    }
+    fs.writeFileSync(path.join(dir,'bad.json'),'{');
+    const malformed=spawnSync(process.execPath,['stream-framer.js',path.join(dir,'bad.json')],{encoding:'utf8'});
+    assert.equal(malformed.status,2);assert.equal(malformed.stdout,'');assert.notEqual(malformed.stderr,'');
+    const missing=spawnSync(process.execPath,['stream-framer.js'],{encoding:'utf8'});
+    assert.equal(missing.status,2);assert.equal(missing.stdout,'');assert.notEqual(missing.stderr,'');
+    const extra=spawnSync(process.execPath,['stream-framer.js',path.join(dir,'input.json'),'extra'],{encoding:'utf8'});
+    assert.equal(extra.status,2);assert.equal(extra.stdout,'');assert.notEqual(extra.stderr,'');
+  }finally{fs.rmSync(dir,{recursive:true,force:true});}
+});

