import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

test('decoder retains completion and failure edge cases',()=>{
  for(const suffix of ['data: [DONE]\n\n',': comment\n','x: ignored\n','event: late\n','data: late\n']){
    const d=createDecoder();
    assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
    assert.throws(()=>d.push(Buffer.from(suffix)),Error);
  }
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event: first\nevent: last\ndata:  one\ndata: a\r\r\n\n')),[{event:'last',data:' one\na\r'}]);
  assert.throws(()=>d.finish(),Error);
  const pending=createDecoder();pending.push(Buffer.from('data: [DONE]\n'));
  assert.throws(()=>pending.finish(),Error);
  const utf8=createDecoder();utf8.push(Buffer.from('data: [DONE]\n\n'));
  utf8.push(Uint8Array.of(0xc3));assert.throws(()=>utf8.finish(),Error);
  const once=createDecoder();once.push(Buffer.from('data: [DONE]\n\n'));assert.deepEqual(once.finish(),[]);assert.throws(()=>once.finish(),Error);
  const partial=createDecoder();
  const earlier=partial.push(Buffer.from('data: kept\n\n'));
  assert.deepEqual(earlier,[{event:'message',data:'kept'}]);
  assert.throws(()=>partial.push(Uint8Array.of(0xc3,0x28)),Error);
  assert.deepEqual(earlier,[{event:'message',data:'kept'}]);
});

test('CLI handles large frame batches and rejects malformed UTF-8 files',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'framer-'));
  try{
    const file=path.join(dir,'large.json');
    const wire='data: x\n\n'.repeat(150000)+'data: [DONE]\n\n';
    fs.writeFileSync(file,JSON.stringify({chunks:[Buffer.from(wire).toString('base64')]}));
    const large=spawnSync(process.execPath,['stream-framer.js',file],{encoding:'utf8',maxBuffer:16*1024*1024});
    assert.equal(large.status,0);assert.equal(large.stderr,'');
    const frames=JSON.parse(large.stdout).frames;
    assert.equal(frames.length,150000);
    assert.deepEqual(frames[0],{event:'message',data:'x'});
    assert.deepEqual(frames.at(-1),{event:'message',data:'x'});
    const malformed=path.join(dir,'malformed.json');
    fs.writeFileSync(malformed,Buffer.concat([Buffer.from('{"chunks":["ZGF0YTogW0RPTkVdCgo="],"extra":"'),Buffer.from([0xff]),Buffer.from('"}') ]));
    const bad=spawnSync(process.execPath,['stream-framer.js',malformed],{encoding:'utf8'});
    assert.equal(bad.status,2);assert.equal(bad.stdout,'');assert.notEqual(bad.stderr,'');
  }finally{fs.rmSync(dir,{recursive:true,force:true});}
});

